export function validateRepositoryValidationCompleted(value: unknown, path: string, contract: string): void {
  if (!isRecord(value)) fail(contract, path, "expected object");
  const record = value as JsonRecord;
  if (!Object.hasOwn(record, "state")) fail(contract, `${path}.state`, "missing required property");
  if (!Object.hasOwn(record, "environment")) fail(contract, `${path}.environment`, "missing required property");
  if (!Object.hasOwn(record, "security_audit")) fail(contract, `${path}.security_audit`, "missing required property");
  if (!Object.hasOwn(record, "tests")) fail(contract, `${path}.tests`, "missing required property");
  for (const [key, item] of Object.entries(record)) {
    switch (key) {
        case "environment": {
          if (!(["VALID", "INVALID"] as unknown[]).includes(item)) fail(contract, `${path}.environment`, "was not an allowed enum value");
          if (typeof item !== "string") fail(contract, `${path}.environment`, "expected string");
          break;
        }
        case "security_audit": {
          if (!(["PASSED", "VULNERABILITIES_FOUND", "UNAVAILABLE", "NOT_SUPPORTED", "SKIPPED"] as unknown[]).includes(item)) fail(contract, `${path}.security_audit`, "was not an allowed enum value");
          if (typeof item !== "string") fail(contract, `${path}.security_audit`, "expected string");
          break;
        }
        case "state": {
          if (item !== "repository_completed") fail(contract, `${path}.state`, "did not match required constant");
          if (typeof item !== "string") fail(contract, `${path}.state`, "expected string");
          break;
        }
        case "tests": {
          if (!(["PASSED", "FAILED"] as unknown[]).includes(item)) fail(contract, `${path}.tests`, "was not an allowed enum value");
          if (typeof item !== "string") fail(contract, `${path}.tests`, "expected string");
          break;
        }
      default: {
        fail(contract, `${path}.${key}`, "unexpected property");
      }
    }
  }
}
